window.EXAMDATA=window.EXAMDATA||{lessons:[],qs:[],terms:[]};
EXAMDATA.lessons.push(
 {id:'FL-5.1.1',ch:5,k:'K2',title:'Purpose and content of a test plan',
  plain:"A test plan is the written plan for how testing will be done. It describes what will be tested, how, by whom and by when. It guides the team and tells stakeholders what to expect. It is updated as the project changes.",
  coffee:"Like the plan for opening a new coffee shop: the menu to test, who runs the machines, the opening date and what could go wrong.",
  points:["Purpose: guide the test work, show how objectives will be met within constraints, and communicate with the team and stakeholders","Typical content: context of testing (scope, objectives, test basis), assumptions and constraints, stakeholders (roles, responsibilities, training needs), communication (forms and frequency)","Also: risk register (product and project risks), and the test approach (levels, types, techniques, deliverables, entry and exit criteria, independence, metrics, test data and environment needs)","Also: budget and schedule; the plan also shows that testing follows the test policy and test strategy, or explains why it deviates","Planning is ongoing: the plan is revised using feedback from test monitoring and control"],
  trap:"A test plan is not a list of test cases or defects; it is the plan for the whole test effort."},
 {id:'FL-5.1.2',ch:5,k:'K1',title:"Tester's contribution to iteration and release planning",
  plain:"In agile projects testers join planning sessions. At release planning they help write testable user stories and acceptance criteria, join risk analysis, estimate test effort and shape the test approach. At iteration planning they do detailed risk analysis of stories, check they are testable, break them into tasks and estimate the test work.",
  coffee:"Before a new seasonal menu launches, the barista checks each new drink can actually be made and tasted properly, and says how long that takes.",
  points:["Release planning: take part in writing testable user stories and acceptance criteria","Release planning: take part in project and product (quality) risk analysis, estimate test effort for the stories, determine the test approach and plan the testing for the release","Iteration planning: analyse and judge the testability of user stories","Iteration planning: do detailed risk analysis of the stories, break them into tasks (especially test tasks), and estimate the test effort for all test tasks","Iteration planning: identify and refine the functional and non-functional aspects of the test object"],
  trap:"Testers do not own the release date or write the production code; they bring testability, risk and effort knowledge to planning."},
 {id:'FL-5.1.3',ch:5,k:'K2',title:'Entry criteria and exit criteria',
  plain:"Entry criteria are the conditions that should be true before a test activity starts. Exit criteria are the conditions that show the activity can be called finished. In agile, the definition of ready works like entry criteria for a story and the definition of done works like exit criteria.",
  coffee:"Entry: the machine is clean, beans and milk are in before the shop opens. Exit: the till is counted and the shop is locked before you go home.",
  points:["Entry criteria: preconditions to start, e.g. resources available (people, tools, environments, test data, budget, time), testware available (test basis, testable requirements, test cases), and an initial quality level of the test object (e.g. smoke tests passed)","Exit criteria: what must be achieved to declare completion, e.g. measures of thoroughness (coverage level, unresolved defects, defect density, failed tests) and yes/no items (planned tests executed, all defects found are reported)","Agile: definition of ready (entry criteria a story must meet before development or testing starts) and definition of done (exit criteria, the team's objective measures for a releasable item)","Both are defined for each test level and differ with the test objectives; running out of time or budget can also act as an exit criterion if stakeholders accept the risk","Skipping unmet entry criteria makes the activity harder, slower, costlier and riskier"],
  trap:"Do not swap them: entry criteria are about starting, exit criteria are about finishing."},
 {id:'FL-5.1.4',ch:5,k:'K3',title:'Estimation techniques for test effort',
  plain:"Estimating means predicting how much test effort is needed; the result rests on assumptions and always carries some error. Four techniques are in the syllabus. Ratio-based uses ratios from past projects. Extrapolation uses early measurements from this project to approximate the rest. Wideband Delphi uses expert estimates with discussion. Three-point estimation combines optimistic, most likely and pessimistic cases.",
  coffee:"Ratio: last year a shop with 3 baristas needed 2 trainers, so a new 6-barista shop needs about 4. Three-point: how long to learn the new grinder at best, most likely and worst.",
  points:["Ratio-based (metrics-based): use ratios from the organisation's own past projects, e.g. dev:test effort of 3:2, so 600 dev person-days gives 400 test person-days","Extrapolation: measure early in the project, then approximate the remaining work from that data, e.g. the average of the last three iterations (18, 20 and 22 days) gives 20 days for the next one","Wideband Delphi: experts estimate in isolation, discuss out-of-range deviations, then re-estimate until consensus; planning poker is a variant","Three-point: E = (a + 4m + b) / 6 and SD = (b - a) / 6, where a = optimistic, m = most likely, b = pessimistic","Worked example: a = 6, m = 9, b = 18 person-hours gives E = (6 + 36 + 18) / 6 = 10 and SD = (18 - 6) / 6 = 2, so 10 plus or minus 2 (8 to 12)"],
  trap:"In three-point estimation the most likely value counts 4 times, so you divide by 6 (not 3); the SD is (b - a) / 6."},
 {id:'FL-5.1.5',ch:5,k:'K3',title:'Test case prioritisation',
  plain:"You rarely have time to run every test, so you decide the order. Common approaches are risk-based, coverage-based and requirements-based ordering. Dependencies between tests must also be respected, which can override the pure priority order.",
  coffee:"Check the espresso machine and the card reader before the biscuit display. If you must make the milk before the latte, that order is fixed.",
  points:["Risk-based: run tests for the highest risk (likelihood x impact) first","Coverage-based: run first the tests that achieve the highest coverage (a variant picks, each time, the test adding the most additional coverage)","Requirements-based: order by the priority the stakeholders gave the requirements the tests cover","Dependencies: if a higher-priority test depends on a lower-priority one, the lower-priority one runs first","Resources count too: tools, environments or people that are only available in a certain time window affect the execution order","Worked example: Pay (risk high) needs a customer from Create account (risk medium); Help page is low. Order: Create account, Pay, Help page"],
  trap:"The highest-priority test is not always run first; a dependency can force an earlier, lower-priority test ahead of it."},
 {id:'FL-5.1.6',ch:5,k:'K1',title:'The test pyramid',
  plain:"The test pyramid is a picture showing that you should have many small, fast, low-level tests and fewer big, slow, high-level tests. Going up the pyramid, tests cover more, take longer and are less isolated. It guides how to spread automated tests.",
  coffee:"Many quick checks on each ingredient (bottom), fewer tests of a whole finished coffee order (top).",
  points:["Models different test granularities (layers) and the number of tests at each","Bottom layer: small, isolated, fast tests, e.g. unit tests; the most tests","Top layer: large, end-to-end tests; slower; fewer tests","Higher layer: lower granularity, less isolation, longer execution time","Common layers: unit, integration (service/API), end-to-end (UI)"],
  trap:"The wide base means MANY tests at the bottom; remembering it the other way round loses the mark."},
 {id:'FL-5.1.7',ch:5,k:'K2',title:'Testing quadrants',
  plain:"The testing quadrants, from agile practice, group test levels, test types and techniques into four boxes. One axis is business-facing or technology-facing. The other axis is supporting the team or critiquing the product. They help make sure no kind of testing is forgotten.",
  coffee:"Checking the grinder works (technology, helps the team build) versus customers tasting the final cup (business, judges the product).",
  points:["Q1: technology-facing, support the team: component and component integration tests, usually automated","Q2: business-facing, support the team: functional tests, user story tests, API tests, prototypes and simulations","Q3: business-facing, critique the product: exploratory testing, usability testing, user acceptance testing","Q4: technology-facing, critique the product: smoke tests and non-functional tests (except usability), e.g. performance and security","They help the team see that all appropriate test levels and types are covered, and explain test types to developers, testers and business people"],
  trap:"Usability sits in Q3 (business-facing), not Q4, even though it is non-functional."},
 {id:'FL-5.2.1',ch:5,k:'K1',title:'Risk level from likelihood and impact',
  plain:"A risk is something that might go wrong. Its level depends on two things: how likely it is and how bad the effect would be. Together they give the risk level, which can be a label like high, medium, low or a number.",
  coffee:"A burnt milk jug is likely but cheap (low-ish); a broken boiler is unlikely but costly. You rate both by chance and damage.",
  points:["Risk = potential event with a negative result","Risk level is made from likelihood (probability of occurring, above 0 and below 1) and impact (harm if it does)","Quantitative: level = likelihood x impact; qualitative: level read from a risk matrix (e.g. high/medium/low)","High likelihood and high impact give the highest risk level","The level is used to decide how much attention the risk gets"],
  trap:"Risk level is not severity plus priority, and not cost plus schedule."},
 {id:'FL-5.2.2',ch:5,k:'K2',title:'Project risks and product risks',
  plain:"Project risks threaten the project itself: schedule, budget, people, suppliers, tools. Product risks are about the software not doing what users need: wrong results, slow, insecure, hard to use. Testing mainly helps reduce product risks, but test management must watch both.",
  coffee:"A barista quitting before opening day is a project risk. A latte machine that sometimes serves cold milk is a product risk.",
  points:["Project risks: organisational (late deliveries, inaccurate estimates, cost cutting), people (skills, conflicts, staff shortage), technical (scope creep, poor tool support), supplier (third-party failure)","Product risks: missing or wrong functions, wrong calculations, poor performance, poor usability, security holes","Project risks hit schedule, budget or scope; product risks relate to product quality characteristics and cause harm such as user dissatisfaction or lost revenue","Examples of project risk: late test environment, key tester leaves","Examples of product risk: wrong totals, slow response, data loss"],
  trap:"A late test environment looks like a testing issue but is a project risk, not a product risk."},
 {id:'FL-5.2.3',ch:5,k:'K2',title:'Product risk analysis: thoroughness and scope',
  plain:"Product risk analysis finds and rates the risks in the product. The results decide what to test, how deeply, and in what order. High-risk areas get more thorough testing, stronger techniques and earlier attention; low-risk areas get less.",
  coffee:"You check the card machine many times before opening but only glance at the napkin holder.",
  points:["Risk identification: find the product risks; risk assessment: rate likelihood and impact","Results decide test scope: which test levels and types are needed","Results decide thoroughness: which techniques and how much coverage","Results decide test order and effort: highest-risk items tested first, effort estimated per task","Can also show whether activities other than testing would reduce risk, e.g. training"],
  trap:"Risk analysis does not remove the need for testing low-risk areas completely; it changes the depth."},
 {id:'FL-5.2.4',ch:5,k:'K2',title:'Responses to analysed product risks',
  plain:"After a risk is analysed you choose a response. You can reduce it (mitigation), live with it (acceptance), pass it to someone else (transfer) or prepare a fallback (contingency plan). Testing is a common way to mitigate product risks.",
  coffee:"Mitigate: train staff on the machine. Accept: ignore a rarely used menu item. Transfer: insure against stock theft. Contingency: keep a backup grinder.",
  points:["Mitigation by testing: suitable experienced testers, appropriate independence, reviews and static analysis, suitable techniques and coverage, suitable test types, dynamic and regression testing","Acceptance: decide the risk is small enough to live with","Transfer: shift the loss to a third party, e.g. insurance or contract","Contingency plan: prepared actions to take if the risk happens","Risk control = mitigation plus risk monitoring (are mitigations working, new information, emerging risks)"],
  trap:"Contingency is what you do AFTER it happens; mitigation acts BEFORE to reduce it."},
 {id:'FL-5.3.1',ch:5,k:'K1',title:'Metrics used for testing',
  plain:"Test metrics are numbers that show how testing is going and how good the product is. They are collected during and at the end of testing to monitor progress, judge quality and decide what to do next.",
  coffee:"Cups sold per hour, wasted milk and customer complaints are the shop's metrics.",
  points:["Project progress metrics: task completion, resource use, test effort","Test progress metrics: test case implementation progress, environment preparation, test cases run/not run, passed/failed, test execution time","Product quality metrics: availability, response time, mean time to failure","Defect metrics: number and priorities of defects found/fixed, defect density, defect detection percentage","Risk (residual risk level), coverage (requirements, code) and cost (cost of testing, organisational cost of quality) metrics"],
  trap:"Do not mix up the groups: requirements coverage is a coverage metric, not a defect metric."},
 {id:'FL-5.3.2',ch:5,k:'K2',title:'Test reports: purpose, content and audience',
  plain:"A test report tells people what testing found. A test progress report is written regularly during testing and helps the team adjust the plan. A test completion report is written once, when a test level, cycle, iteration or project is complete. What you include depends on who reads it.",
  coffee:"The daily till report is a progress report; the end-of-month report to the owner is a completion report.",
  points:["Purpose: describe progress and results, and support decisions","Progress report (also called a test status report): regular (e.g. daily or weekly); testing period, progress and notable deviations, impediments and workarounds, metrics, new and changed risks, testing planned for the next period","Completion report: prepared when a project, test level or test type is complete (ideally exit criteria met); test summary, quality evaluation against the plan, deviations, impediments, metrics, unmitigated risks, defects not fixed, lessons learned","Audience decides the formality and frequency: reporting inside the team is often frequent and informal; completion reporting follows a set template and happens once","Progress reports feed test control; completion reports build on the progress reports and give information for later testing"],
  trap:"The v4.0 name is test completion report (not 'summary report'); it closes an activity and lists unmitigated risks and lessons learned."},
 {id:'FL-5.3.3',ch:5,k:'K2',title:'Communicating the status of testing',
  plain:"How you share test status depends on test management concerns, the organisation's strategy, regulations and the team itself, and different stakeholders want different information. Options include verbal updates, dashboards, task boards, emails and formal reports. Agile teams often use daily stand-ups and visible boards.",
  coffee:"A whiteboard by the machine showing which orders are in, plus a quick huddle at the start of the shift.",
  points:["Verbal communication, e.g. stand-up meetings and team chat","Dashboards (CI/CD, task boards, burn-down charts)","Electronic channels: email, chat","Online documents and formal test reports","One or more options can be combined; tailor the content to each stakeholder; more formal communication suits distributed teams that cannot meet face to face"],
  trap:"No single method is always correct; the best choice fits the audience and context."},
 {id:'FL-5.4.1',ch:5,k:'K2',title:'Configuration management and testing',
  plain:"Configuration management identifies, controls and tracks work products such as test plans, test cases, scripts, results and reports, and their versions. It lets testers know exactly what they tested and reproduce results. It also keeps links between items so changes can be traced.",
  coffee:"Like labelling each recipe with a version number so you know which one a barista used for a bad batch.",
  points:["Configuration items (including test items) are uniquely identified, version controlled and tracked for change","Relationships between items are kept, giving traceability through the process","Covers work products such as test plans, test cases, scripts, results, logs and reports, and the parts of a test environment","Documentation and software items are referenced unambiguously in testware; automated CM is normally part of a DevOps pipeline","An approved item becomes a baseline that changes only through formal change control; you can revert to an earlier baseline to reproduce earlier results"],
  trap:"Configuration management is not about test techniques; it is about identifying and controlling versions."},
 {id:'FL-5.5.1',ch:5,k:'K3',title:'Preparing a defect report',
  plain:"A defect report lets people understand, reproduce and fix a failure. A good one has clear facts and no blame. Typical fields cover identity, where it was found, what happened and what was expected, how bad it is, how urgent, and where it stands in the defect workflow.",
  coffee:"Telling the repairer: which machine, what you pressed, what you expected, what came out and a photo.",
  points:["Identification: unique identifier, title with short summary, date observed, issuing organisation and author (with role)","Where: test object and test environment, context (test case being run, test activity, SDLC phase, technique, checklist or test data used)","What: description of the failure so it can be reproduced (steps, logs, screenshots, video), expected result and actual result","How bad: severity (degree of impact on stakeholders or requirements) and priority to fix; status (e.g. open, deferred, duplicate, re-opened, closed, rejected); references (e.g. to the test case)","Defect workflow: log the anomaly, analyse and classify it, decide a response (e.g. fix or keep as is), then close; anomalies may turn out to be false positives or change requests"],
  trap:"Severity is the technical impact; priority is how urgently the business wants it fixed, so they can differ."}
);
EXAMDATA.qs.push(
 {id:'c5-001',ch:5,lo:'FL-5.1.1',k:'K2',q:"Which statement best explains the purpose of a test plan?",o:["It lists the failures found during test execution, with their severity and status, so developers can sort them for fixing.", "It gives the detailed steps and expected results of every individual test, for testers to follow during execution.", "It describes the objectives, resources, approach and schedule for the testing and helps communicate them to stakeholders.", "It traces each requirement to the code implementing it, so reviewers can follow the design decisions."],a:2,why:"Correct: a test plan documents the means and schedule for reaching the test objectives and communicates them. The failure list is defect reporting, the step-by-step detail is test procedures or test cases, and requirement-to-code tracing is design or traceability documentation, not planning."},
 {id:'c5-002',ch:5,lo:'FL-5.1.1',k:'K2',q:"Which item would you expect to find in a test plan?",o:["Entry and exit criteria for each test level, plus the metrics that will be collected", "The actual results and logs recorded during last night's automated test run on the build", "The source code of the component under test, together with its full change history", "A defect report with the steps needed to reproduce a failure seen during execution"],a:0,why:"Correct: entry and exit criteria and the metrics to collect belong to the test approach in the plan. Actual results are execution output (test logs), the source code is the test object, and a defect with reproduction steps is part of a defect report."},
 {id:'c5-003',ch:5,lo:'FL-5.1.1',k:'K2',q:"A test plan says: 'A progress report goes to the shop owner every Friday; blocking defects are discussed with the developers at a daily 09:00 call.' Which test plan content does this illustrate?",o:["Test approach: the techniques chosen for performance testing", "Risk register: the product risks and their ratings in a list", "Communication: forms and frequency of reporting and calls", "Budget: the money allowed for tools and training of testers"],a:2,why:"Correct: who is told what, how and how often is the communication content. The statement says nothing about techniques (approach), listed risks with ratings (risk register) or money (budget)."},
 {id:'c5-004',ch:5,lo:'FL-5.1.2',k:'K1',q:"In iteration planning for an agile team, which is a typical tester contribution?",o:["Writing the production code for the user stories and then fixing the defects that testing finds", "Setting the overall project budget for the whole product release and approving the spending", "Judging the testability of user stories and breaking them into tasks, including test tasks", "Accepting the release date on behalf of the paying customer after the demo"],a:2,why:"Correct: in iteration planning testers judge testability, break stories into tasks and estimate the test work. Writing production code is the developers' job, the budget is a management decision and the release date is the business's decision."},
 {id:'c5-005',ch:5,lo:'FL-5.1.2',k:'K1',q:"Which is a typical tester contribution at release planning?",o:["Choosing the programming language, the architecture and the coding standards for the product", "Writing the release notes that end users will read once the new version has been launched", "Selecting the hosting provider and the server set-up for the production environment", "Helping write testable user stories and acceptance criteria, and estimating test effort"],a:3,why:"Correct: at release planning testers help write testable stories and acceptance criteria, join risk analysis and estimate test effort. Choosing language, architecture and hosting are technical decisions for others, and release notes are not a specifically tester task."},
 {id:'c5-006',ch:5,lo:'FL-5.1.3',k:'K2',q:"Which is an example of an exit criterion for system testing?",o:["The test environment has been installed, configured and is available for the testers", "All planned tests have been run and no critical defect remains unresolved", "Test data has been loaded and the testers have been trained on the tool", "The requirements have been approved by the business owner and are testable"],a:1,why:"Correct: planned tests executed and the number of unresolved defects are measures of thoroughness that show when the activity can be called complete. A working environment and loaded data with trained testers are resources to have before starting (entry), and approved requirements are testware available at the start."},
 {id:'c5-007',ch:5,lo:'FL-5.1.3',k:'K2',q:"Which statement best compares entry criteria and exit criteria?",o:["Entry criteria are preconditions for undertaking an activity; exit criteria define what must be achieved to declare it complete.","Entry criteria are used only in agile projects, while exit criteria are used only in sequential projects.","Entry criteria describe the product risks to be accepted, while exit criteria list the project risks that remain.","Entry criteria are set by the testers alone, while exit criteria are decided by the developers alone."],a:0,why:"Correct: start conditions versus completion conditions, defined for each test level. Both exist in every lifecycle, neither is about risk types, and ownership is not split between testers and developers."},
 {id:'c5-008',ch:5,lo:'FL-5.1.3',k:'K2',q:"In agile development, which concept plays the role of exit criteria for a user story?",o:["The sprint backlog","The definition of ready","The definition of done","The retrospective"],a:2,why:"Correct: the definition of done states the team's objective measures for a releasable item. The sprint backlog is a list of work, the definition of ready is the entry-criteria counterpart, and the retrospective is a process-improvement meeting."},
 {id:'c5-009',ch:5,lo:'FL-5.1.3',k:'K2',q:"A team is about to start system testing but finds that the build is not yet deployed and the test cases are not written. Which concept have they just checked?",o:["Exit criteria","Entry criteria","Risk acceptance","Test completion reporting"],a:1,why:"Correct: availability of the test object and testware are preconditions to start, which are entry criteria. Exit criteria relate to finishing, risk acceptance is a risk response, and completion reporting happens at the end."},
 {id:'c5-010',ch:5,lo:'FL-5.1.6',k:'K1',q:"According to the test pyramid, which layer should contain the most tests?",o:["End-to-end tests that drive the complete user interface","Exploratory system tests performed by experienced testers","Acceptance tests carried out by the business users","Small, fast, isolated tests such as unit tests"],a:3,why:"Correct: the wide bottom layer holds many small, isolated, fast tests. End-to-end, exploratory and acceptance tests sit higher, are slower and cover more, so fewer are needed."},
 {id:'c5-011',ch:5,lo:'FL-5.1.6',k:'K1',q:"Moving up the layers of the test pyramid, tests tend to be:",o:["Larger in scope, slower to run and fewer in number","Smaller in scope, quicker to run, more isolated and more numerous","More isolated and cheaper to run than the layers below","Limited to checking single functions in one component"],a:0,why:"Correct: higher layers have lower granularity, less isolation, longer execution time and need fewer tests. Smaller, quicker, more isolated tests describe the bottom, being more isolated is the opposite of the trend, and single-function checks are unit tests at the base."},
 {id:'c5-012',ch:5,lo:'FL-5.1.7',k:'K2',q:"Component tests and component integration tests belong to which quadrant?",o:["Q4 (technology-facing, critique the product)", "Q3 (business-facing, critique the product)", "Q1 (technology-facing, support the team)", "Q2 (business-facing, support the team)"],a:2,why:"Correct: Q1 is technology-facing and supports the team; its tests should be automated and run in the CI process. Q2 is business-facing support (functional and story tests), Q3 is business-facing critique (exploratory, usability, acceptance) and Q4 is technology-facing critique (smoke and non-functional tests)."},
 {id:'c5-013',ch:5,lo:'FL-5.1.7',k:'K2',q:"A team has testers freely explore the new checkout looking for problems, and real customers then try it out to judge whether it suits them. Which quadrant do these tests belong to?",o:["Q1: technology-facing, supporting the team","Q2: business-facing, supporting the team","Q4: technology-facing, critiquing the product","Q3: business-facing, critiquing the product"],a:3,why:"Correct: exploratory and user acceptance testing are business-facing and critique the product (Q3). Q1 holds component-level tests, Q2 holds functional and user story tests that check acceptance criteria, and Q4 holds smoke and non-functional tests such as performance and security."},
 {id:'c5-014',ch:5,lo:'FL-5.1.7',k:'K2',q:"Performance and security testing are usually placed in which quadrant?",o:["Q1: technology-facing, supports the team during development", "Q2: business-facing, supports the team through examples", "Q3: business-facing, critiques the product through user feedback", "Q4: technology-facing, critiques the product itself"],a:3,why:"Correct: non-functional tests other than usability are technology-facing and critique the product (Q4). Q1 is component tests, Q2 is functional and story tests, and Q3 is exploratory, usability and acceptance testing."},
 {id:'c5-015',ch:5,lo:'FL-5.1.7',k:'K2',q:"Which statement best explains how the testing quadrants relate to test levels and test types?",o:["They group levels and types by business versus technology focus and by supporting the team versus critiquing the product.","They rank every test type from most to least important for any project, whatever its context or risks.","They match the five test levels one to one, giving each level its own quadrant and a fixed place.","They define the fixed order in which the test types must be executed in each iteration."],a:0,why:"Correct: the two axes organise levels, types, techniques and work products so none is forgotten. The model does not rank importance, does not map levels one to one (a quadrant can hold several, and there are four quadrants versus five levels), and does not set an execution order."},
 {id:'c5-016',ch:5,lo:'FL-5.2.1',k:'K1',q:"The level of a risk is determined from which two factors?",o:["Likelihood of the event and its impact", "Cost and schedule of the project plan", "Severity and priority of the defect", "Size and complexity of the whole product"],a:0,why:"Correct: risk level expresses risk likelihood and risk impact. Cost and schedule are project constraints, severity and priority are defect attributes, and size and complexity are product characteristics."},
 {id:'c5-017',ch:5,lo:'FL-5.2.1',k:'K1',q:"Using a 1 to 5 scale for each factor, which risk has the highest risk level?",o:["Likelihood 2, impact 5: rare but with severe harm", "Likelihood 4, impact 4: likely and quite harmful", "Likelihood 5, impact 2: very likely but minor harm", "Likelihood 3, impact 3: moderate on both"],a:1,why:"Correct: likelihood times impact gives 16 for likelihood 4 and impact 4. The others give 10 (likelihood 2, impact 5), 10 (likelihood 5, impact 2) and 9 (likelihood 3, impact 3)."},
 {id:'c5-018',ch:5,lo:'FL-5.2.1',k:'K1',q:"How can a risk level be determined?",o:["Only by estimating the amount of money that would be lost","Quantitatively by multiplying likelihood and impact, or qualitatively using a risk matrix","Only by counting the defects already found in the same area","Only by asking the project sponsor how worried they feel"],a:1,why:"Correct: quantitative assessment multiplies likelihood by impact and qualitative assessment reads the level from a risk matrix (or a mix of both). Money, defect counts or the sponsor's feelings alone are not how risk level is defined."},
 {id:'c5-019',ch:5,lo:'FL-5.2.2',k:'K2',q:"Which of the following is a project risk?",o:["The payment calculation may round amounts incorrectly for some currencies and tax rates", "The app may respond too slowly when a large number of users log in together", "The only experienced tester may leave the team before system testing starts", "Users may find the login screen hard to understand and use on a small phone screen"],a:2,why:"Correct: staff shortage is a people issue that threatens schedule and objectives of the project. Wrong rounding, slow response under load and poor usability are product risks about product quality."},
 {id:'c5-020',ch:5,lo:'FL-5.2.2',k:'K2',q:"Which of the following is a product risk?",o:["The test environment will be delivered two weeks late","The team lacks experience with the chosen test tool","The app may charge customers the wrong amount","A supplier may deliver a component late"],a:2,why:"Correct: wrong charging is a risk to product quality (incorrect calculation). A late environment, missing tool skills and a late supplier delivery threaten the project's schedule, so they are project risks."},
 {id:'c5-021',ch:5,lo:'FL-5.2.2',k:'K2',q:"Which statement best distinguishes project risks from product risks?",o:["Project risks concern software quality, while product risks concern schedule and budget.","Project risks occur only before testing starts, while product risks occur only after release.","Product risks are handled only by managers, while project risks are handled only by testers.","Project risks relate to managing and controlling the project, while product risks relate to product quality characteristics."],a:3,why:"Correct: project risks affect schedule, budget or scope; product risks relate to quality characteristics of the product. One option reverses the two, another invents a timing rule, and the last invents an ownership rule."},
 {id:'c5-022',ch:5,lo:'FL-5.2.3',k:'K2',q:"How does product risk analysis influence the testing of an area rated as high risk?",o:["Less testing is done, because the team already knows the area is difficult and risky", "More thorough testing with stronger techniques, run earlier than the tests for other areas", "No change at all, because every area is tested equally, whatever its risk rating happens to be", "Testing is postponed until after release, when real users report any problems they meet"],a:1,why:"Correct: higher risk earns more coverage, stronger techniques and earlier execution. Reducing testing reverses the logic, equal testing ignores the analysis, and postponing leaves the risk uncontrolled."},
 {id:'c5-023',ch:5,lo:'FL-5.2.3',k:'K2',q:"What can the results of a product risk analysis be used to decide?",o:["Which test levels and types are needed, which techniques and coverage to use, and in what order to test","The salaries and working hours of the people in the testing team","Whether the test plan can be replaced entirely by the risk list","Whether exit criteria are needed for any of the test levels"],a:0,why:"Correct: scope, techniques, coverage, effort and order all follow from the analysis. Salaries are unrelated, the risk list feeds the plan rather than replacing it, and exit criteria stay necessary."},
 {id:'c5-024',ch:5,lo:'FL-5.2.3',k:'K2',q:"The checkout payment feature is rated high risk and the help page low risk. Which test approach best reflects risk-based thinking?",o:["Give both areas exactly the same number of tests, the same techniques and the same effort overall", "Test the help page in more depth, because it is the easier area and quick to check", "Skip checkout testing for now, because it is the most complex and expensive area", "More tests and stronger techniques for checkout, lighter testing for the help page"],a:3,why:"Correct: effort and thoroughness follow risk. Equal effort ignores risk, deeper testing of the low-risk page reverses the priority, and skipping checkout leaves the biggest risk untested."},
 {id:'c5-025',ch:5,lo:'FL-5.2.4',k:'K2',q:"Which is an example of mitigating a product risk by testing?",o:["Buying insurance that pays out if customer data is lost in a breach", "Writing a plan for what to do if the server crashes at launch time", "Running extra performance tests early to find slowdowns sooner", "Deciding to launch without checking a rarely used report at all"],a:2,why:"Correct: extra early testing lowers the risk level. Insurance is risk transfer, a plan for after a crash is a contingency plan, and launching without checking is risk acceptance."},
 {id:'c5-026',ch:5,lo:'FL-5.2.4',k:'K2',q:"The business decides not to test a rarely used legacy report and accepts that it may contain errors. Which risk response is this?",o:["Mitigation","Transfer","Contingency planning","Acceptance"],a:3,why:"Correct: knowingly living with the risk is acceptance. Mitigation reduces the risk, transfer shifts the loss to a third party, and a contingency plan prepares fallback actions."},
 {id:'c5-027',ch:5,lo:'FL-5.2.4',k:'K2',q:"A coffee shop buys cyber insurance so that a card-data leak is paid for by the insurer. Which risk response is this?",o:["Transfer","Mitigation","Acceptance","Contingency planning"],a:0,why:"Correct: the financial loss is shifted to a third party, which is risk transfer. Mitigation lowers likelihood or impact itself, acceptance means doing nothing, and a contingency plan is a prepared fallback."},
 {id:'c5-028',ch:5,lo:'FL-5.3.1',k:'K1',q:"Which of the following is a product quality metric?",o:["Number of testers in the team","Planned versus actual test hours","Mean time to failure","Percentage of requirements covered by tests"],a:2,why:"Correct: mean time to failure (like availability and response time) describes product quality. Team size and planned versus actual hours are project progress or effort figures, and requirements coverage is a coverage metric."},
 {id:'c5-029',ch:5,lo:'FL-5.3.1',k:'K1',q:"Which metric group does 'percentage of requirements covered by at least one test' belong to?",o:["Cost metrics, which track what testing spends", "Defect metrics, which count and rate the defects found", "Risk metrics, which show the residual risk level", "Coverage metrics, which show how much was tested"],a:3,why:"Correct: requirements coverage is a coverage metric. Cost metrics measure money, defect metrics count and rate defects, and risk metrics measure residual risk."},
 {id:'c5-030',ch:5,lo:'FL-5.3.2',k:'K2',q:"Which statement correctly compares a test progress report and a test completion report?",o:["Both are produced only once, at the very end of the whole project","A progress report is produced regularly during testing, while a completion report summarises a finished activity such as a test level or iteration","A progress report is for managers only, while a completion report is for developers only","A completion report is always shorter than a progress report"],a:1,why:"Correct: progress reports recur and support test control; completion reports close a project, level or type, usually following a set template once. The other statements merge the two, invent audiences and invent a length rule."},
 {id:'c5-031',ch:5,lo:'FL-5.3.2',k:'K2',q:"A test completion report is going to senior management. Which content is most appropriate?",o:["Full stack traces for each failure found during execution","Every line of the test execution log from every run","Evaluation against the exit criteria, unmitigated risks and unfixed defects, in non-technical language","The source code of the automated test scripts"],a:2,why:"Correct: management needs the outcome against the plan and the remaining risks. Stack traces, raw logs and test code are technical detail for the team, not suited to this audience."},
 {id:'c5-032',ch:5,lo:'FL-5.3.2',k:'K2',q:"Which item appears ONLY in a test completion report and not in a typical test progress report?",o:["Testing planned for the next period","Impediments for testing and their workarounds","New and changed risks within the testing period","Lessons learned that are relevant to testing"],a:3,why:"Correct: lessons learned are collected when an activity is complete. Next-period plans, impediments with workarounds, and new or changed risks are standard content of regular progress reports (impediments and metrics also recur in completion reports)."},
 {id:'c5-033',ch:5,lo:'FL-5.3.3',k:'K2',q:"Which is an example of communicating test status in an agile team?",o:["Sending a long printed report to the whole company once every quarter", "Showing progress on a task board and discussing it at the daily stand-up", "Emailing raw defect-database exports to the customer with no comment at all", "Waiting until the retrospective to mention blockers to the rest of the team"],a:1,why:"Correct: dashboards and task boards plus verbal stand-ups are typical frequent channels. A quarterly printout is too slow, raw exports are unclear for the audience, and holding blockers back delays important news."},
 {id:'c5-034',ch:5,lo:'FL-5.3.3',k:'K2',q:"A test manager must give executives a quick view of testing status. Which approach is the best fit?",o:["Send the complete defect database export with all of the test logs attached to it", "Hand over every test script and the full execution history of the whole project", "A short dashboard or report with a few key metrics and the main remaining risks", "Give a verbal update with no figures or supporting data to back it up"],a:2,why:"Correct: communication should be tailored to the audience, and executives want a short, metric-based view. The full export, scripts and history are too detailed, and a figure-free verbal update gives no evidence."},
 {id:'c5-035',ch:5,lo:'FL-5.3.3',k:'K2',q:"A test team is spread over several time zones and cannot meet face to face. Which communication approach suits it best?",o:["Daily face-to-face stand-ups held beside the physical task board in one shared room", "Informal corridor conversations whenever people happen to bump into each other", "Waiting for ad hoc phone calls from whichever stakeholders want an update", "More formal channels, such as online documentation and written test reports"],a:3,why:"Correct: distributed teams without direct contact benefit from more formal communication, such as online documentation and formal reports. Face-to-face stand-ups, corridor chats and waiting for calls all rely on people being together or on chance."},
 {id:'c5-036',ch:5,lo:'FL-5.4.1',k:'K2',q:"How does configuration management support testing?",o:["By selecting the best test technique for each requirement","By estimating the effort needed for each test task","By uniquely identifying and version-controlling items and testware and keeping their relationships traceable","By deciding which risks the business should accept"],a:2,why:"Correct: unique identification, version control, change tracking and traceability are its core. Choosing techniques belongs to test analysis and design, estimating is test planning, and accepting risk is risk management."},
 {id:'c5-037',ch:5,lo:'FL-5.4.1',k:'K2',q:"A defect report says 'failure seen in build 2.3.1 on environment E2'. Which benefit of configuration management does this show?",o:["More accurate effort estimates for the whole test project", "Failures can be reproduced because exact versions and environment are identified", "Lower product risk for every future release of the software", "Faster prioritisation of the test cases in the test suite"],a:1,why:"Correct: unambiguous identification of items lets testers go back to the same baseline and reproduce results. Estimates, product risk and test case prioritisation are not what version identification provides."},
 {id:'c5-038',ch:5,lo:'FL-5.4.1',k:'K2',q:"When a requirement changes, how does configuration management help testers?",o:["It automatically rewrites the affected tests to match the new wording","It removes the need for regression testing after the change","It prevents any change to configuration items from being made","Versions and relationships show which tests relate to which requirement version, so outdated tests can be found"],a:3,why:"Correct: traceability between versioned items reveals what is affected. It does not rewrite tests, it does not remove the need for regression testing, and it does not stop change (it controls it through change control)."},
 {id:'c5-039',ch:5,lo:'FL-5.5.1',k:'K3',q:"A tester tapped Pay with a saved card on an R85.00 order in the coffee app (version 1.4.2, Android 14, staging environment). A spinner showed for 3 minutes and then the app crashed; confirmation was expected within 5 seconds. Which draft defect report is best?",o:["Payment is broken in the app. Please look at it and fix it as soon as you can.","Title: Payment hangs, then app crashes (v1.4.2, Android 14, staging). Steps: add a drink, pay R85.00 with saved card. Expected: confirmation within 5 s. Actual: 3 min spinner, crash. Severity high. Log attached.","The PaymentService timeout setting is probably wrong and the developer should fix it today.","App crashed. It sometimes happens when paying, I think. Not sure about the details."],a:1,why:"Correct: it has a title, version and environment, reproducible steps, expected versus actual result, severity and evidence. The other drafts give no facts, no steps or environment, guess at the cause, or are vague."},
 {id:'c5-040',ch:5,lo:'FL-5.5.1',k:'K3',q:"You are preparing a defect report so that a developer can understand and reproduce a failure. Which set of items should the report contain?",o:["Test estimate, entry criteria, budget and the planned schedule","Coverage target, team velocity, risk matrix and release date","Unique identifier, title, date, author, test object and environment, description of the failure, expected and actual results, severity and priority, status","Release date, contract number, supplier name and sprint goal"],a:2,why:"Correct: these are the typical defect report fields. Planning content (estimate, criteria, budget, schedule), metrics and risk content, and project administration (contract, supplier, sprint goal) do not help someone reproduce a failure."},
 {id:'c5-041',ch:5,lo:'FL-5.5.1',k:'K3',q:"A tester drafts: 'Title: Discount wrong. Steps: apply discount code SAVE10. Result: total is wrong.' Which addition is MOST important?",o:["A proposed code fix written by the tester, for the developers to copy and apply", "The names of everyone in the test team and everyone in the development team", "The test effort estimate and the planned schedule for the whole project", "The expected total, the actual total, and the version and environment used"],a:3,why:"Correct: without expected versus actual results and the environment the developer cannot confirm and reproduce the failure. A fix proposal is not required from the tester, and team names and project estimates do not help reproduce anything."},
 {id:'c5-042',ch:5,lo:'FL-5.5.1',k:'K3',q:"Double-tapping Place Order in the app creates two orders and charges the customer twice. Which draft is best?",o:["Steps: add one drink, double-tap Place Order. Expected: one order, one charge. Actual: two of each. v2.0.1, staging, iPhone 13. Severity high.", "The dev team has been sloppy about taps again. Fix this now and tell me when it is done, because customers are upset about it.", "Orders can be duplicated, and customers will be very unhappy when they notice the extra charges on their cards.", "A 40-page log is attached. There is no description, so please read through all of it and work out what went wrong."],a:0,why:"Correct: it is factual, reproducible and states expected versus actual results with version and environment. The others blame people, lack steps, or dump raw data without a description."},
 {id:'c5-043',ch:5,lo:'FL-5.5.1',k:'K3',q:"The shop's name is misspelled on the home page, the owner needs it fixed before a launch event tomorrow, and the app is otherwise fine. Which severity and priority entries are most appropriate?",o:["Severity low, priority high","Severity high, priority low","Severity high, priority high","Severity low, priority low"],a:0,why:"Correct: little impact on functionality (low severity) but urgent for the business (high priority). The other pairs reverse them, overstate the impact, or ignore the deadline."},
 {id:'c5-044',ch:5,lo:'FL-5.5.1',k:'K3',q:"A developer fixed a logged defect and the tester re-ran the failing steps successfully. Which status should the tester now record?",o:["New","Rejected","Closed","Deferred"],a:2,why:"Correct: a confirmed fix lets the defect report be closed. New is the starting status, rejected is for reports judged not to be defects, and deferred means the fix is postponed."},
 {id:'c5-045',ch:5,lo:'FL-5.1.4',k:'K3',q:"In past projects the development-to-test effort ratio was 5:2. The new project expects 450 person-days of development effort. What test effort does ratio-based estimation give?",o:["225 person-days (half of the development effort)", "300 person-days (using a 3:2 ratio)", "180 person-days (450 x 2 / 5)", "1,125 person-days (450 x 5 / 2)"],a:2,why:"Correct: 450 x 2 / 5 = 180 person-days. 225 simply halves the development effort, 300 uses a 3:2 ratio, and 1,125 inverts the ratio (450 x 5 / 2)."},
 {id:'c5-046',ch:5,lo:'FL-5.1.4',k:'K3',q:"Experts estimate the effort to test a feature as 2 days optimistic, 5 days most likely and 14 days pessimistic. What is the three-point estimate E?",o:["7 days, the plain average of the three figures", "6 days, from (2 + 4 x 5 + 14) / 6", "8 days, the midpoint of best and worst", "5 days, the most likely figure"],a:1,why:"Correct: E = (2 + 4 x 5 + 14) / 6 = 36 / 6 = 6 days. 7 is the plain average (2 + 5 + 14) / 3, 8 is the midpoint of optimistic and pessimistic, and 5 ignores the other two estimates."},
 {id:'c5-047',ch:5,lo:'FL-5.1.4',k:'K3',q:"For a test task the estimates are a = 10 hours, m = 16 hours, b = 34 hours. Which final estimate with its error range does three-point estimation give?",o:["20 hours, with a range of 16 to 24", "18 hours, with a range of 14 to 22", "16 hours, with a range of 12 to 20", "18 hours, with a range of 6 to 30"],a:1,why:"Correct: E = (10 + 64 + 34) / 6 = 18 and SD = (34 - 10) / 6 = 4, giving 14 to 22 hours. The 20-hour answer divides by 3, the 16-hour answer just takes the most likely value, and the 6 to 30 range uses half the spread (12) instead of SD."},
 {id:'c5-048',ch:5,lo:'FL-5.1.4',k:'K3',q:"A team estimates the next iteration's test effort by taking the average of the last three iterations, which needed 12, 15 and 18 person-days. Which technique is this and what is the estimate?",o:["Extrapolation: 15 person-days","Extrapolation: 45 person-days","Wideband Delphi: 15 person-days","Ratio-based estimation: 18 person-days"],a:0,why:"Correct: using measurements from the current project to approximate coming work is extrapolation, and (12 + 15 + 18) / 3 = 15. 45 is the sum, not an average; Wideband Delphi uses repeated expert estimates, and ratio-based estimation uses ratios from past projects."},
 {id:'c5-049',ch:5,lo:'FL-5.1.5',k:'K3',q:"Three test cases are prioritised: A (high), B (medium), C (low). Test A needs data created by running test B first. Which execution order is correct?",o:["A, B, C because the high-priority test goes first", "B, A, C because A needs data from B", "C, B, A because low priority runs first", "A, C, B because B can wait until last"],a:1,why:"Correct: when a higher-priority test depends on a lower-priority one, the lower one must run first, so B, then A, then C. Starting with A breaks the dependency, and the other orders ignore priority or the dependency."},
 {id:'c5-050',ch:5,lo:'FL-5.1.5',k:'K3',q:"Risk scores (likelihood x impact, each 1 to 5) are: Login 3 x 4, Pay 4 x 5, Search 5 x 2, Report 2 x 3. With risk-based prioritisation and no dependencies, which order should the tests run in?",o:["Search, Pay, Login, Report (by likelihood only)", "Pay, Login, Report, Search (by impact only)", "Pay, Login, Search, Report (by likelihood x impact)", "Login, Pay, Search, Report (by the order of the menu)"],a:2,why:"Correct: the scores are Pay 20, Login 12, Search 10, Report 6, so Pay, Login, Search, Report. Sorting by likelihood only or by impact only gives different orders, and starting with Login ignores that Pay has the higher score."},
 {id:'c5-051',ch:5,lo:'FL-5.1.5',k:'K3',q:"Four test cases cover this many statements: T1 40, T2 60, T3 25, T4 45. Using coverage-based prioritisation (highest coverage first), what is the order?",o:["T3, T1, T4, T2 (lowest coverage first)", "T1, T2, T3, T4 (numeric order)", "T2, T4, T1, T3 (highest coverage first)", "T4, T2, T1, T3 (two highest swapped)"],a:2,why:"Correct: ordering by statements covered from most to least gives T2 (60), T4 (45), T1 (40), T3 (25). The reverse order starts with the lowest, numeric order ignores coverage, and swapping the top two puts T4 ahead of T2 although it covers less."},
 {id:'c5-052',ch:5,lo:'FL-5.2.4',k:'K2',q:"After the mitigation actions for a product risk have been started, what is the aim of risk monitoring?",o:["To transfer the remaining risk to an insurer","To check that mitigation works, gather information to improve the assessment, and spot emerging risks","To remove the risk from the risk register permanently","To replace the exit criteria with the risk level"],a:1,why:"Correct: monitoring checks effectiveness of mitigation, improves risk assessment and identifies new risks. Transfer is a separate response, risks are not simply deleted, and exit criteria are not replaced by a risk level."},
 {id:'c5-053',ch:5,lo:'FL-5.4.1',k:'K2',q:"A test environment configuration has been approved for testing and recorded as a baseline. What does this mean for the team?",o:["It can be edited freely by anyone, since all versions are kept","It can only be changed through formal change control, and an earlier baseline can be restored to reproduce earlier results","It no longer needs to be linked to other configuration items","It is automatically excluded from the test report"],a:1,why:"Correct: a baseline changes only via formal change control, and reverting to a previous baseline allows earlier test results to be reproduced. Free editing defeats control, links between items must be kept for traceability, and exclusion from reports is not a baseline feature."},
 {id:'c5-054',ch:5,lo:'FL-5.1.1',k:'K2',q:"Which statement shows how a test plan helps a team beyond simply listing tasks?",o:["It removes the need for test monitoring because everything is decided in advance","Preparing it forces testers to think through risks, schedules, people, tools and costs before the work starts","It guarantees that the schedule will be met without any later changes","It replaces the test policy and the test strategy of the organisation"],a:1,why:"Correct: the planning process guides testers' thinking and makes them confront future challenges. A plan does not remove the need for monitoring and control, cannot guarantee the schedule, and must follow (or explain deviations from) the policy and strategy rather than replace them."}
);
EXAMDATA.terms.push(
 {t:'Test plan',ch:5,d:'A document describing what will be tested, how, by whom and when, used to guide and communicate the test effort.'},
 {t:'Entry criteria',ch:5,d:'Conditions that should be met before a test activity can begin.'},
 {t:'Exit criteria',ch:5,d:'Conditions that show a test activity can be regarded as complete.'},
 {t:'Definition of done',ch:5,d:'An agile team\'s agreed checklist for when a user story counts as finished; it acts like exit criteria.'},
 {t:'Test pyramid',ch:5,d:'A model showing many small, fast, low-level tests at the base and fewer large, slow, high-level tests at the top.'},
 {t:'Testing quadrants',ch:5,d:'A grid grouping tests by business or technology focus and by supporting the team or critiquing the product.'},
 {t:'Risk level',ch:5,d:'How serious a risk is, based on how likely it is and how big its impact would be.'},
 {t:'Project risk',ch:5,d:'A risk to the project\'s schedule, budget, people or suppliers that can stop it meeting its goals.'},
 {t:'Product risk',ch:5,d:'A risk that the software itself fails to meet user or stakeholder needs, for example wrong results or slow performance.'},
 {t:'Risk mitigation',ch:5,d:'Taking action in advance, such as extra testing, to lower the likelihood or impact of a risk.'},
 {t:'Test progress report',ch:5,d:'A report written regularly during testing that shows progress against the plan, impediments, metrics, changed risks and next steps.'},
 {t:'Test completion report',ch:5,d:'A report prepared when a test level, cycle, iteration or project is complete, summarising results against the plan, deviations, unmitigated risks and lessons learned.'},
 {t:'Test estimation',ch:5,d:'Predicting how much effort or time testing will need.'},
 {t:'Wideband Delphi',ch:5,d:'An estimation technique where experts estimate separately, discuss differences and estimate again.'},
 {t:'Three-point estimation',ch:5,d:'Estimating from a best, most likely and worst case: E = (a + 4m + b) / 6 with SD = (b - a) / 6.'},
 {t:'Configuration management',ch:5,d:'Identifying and controlling items and their versions, and keeping them traceable, so you know exactly what was tested.'},
 {t:'Defect report',ch:5,d:'A record of a failure with enough detail, such as steps, expected and actual results and severity, for others to reproduce and fix it.'},
 {t:'Test metric',ch:5,d:'A measured number, such as tests passed or defects found, used to monitor testing and product quality.'}
);
